INSERT INTO potential_categories (id, slug, label, title, summary, image_url, accent_class_name, stat_value, stat_label, detail_eyebrow, detail_intro, detail_description, contact_name, contact_role, contact_email, display_order, is_active, status, seo_title, seo_description, published_at) VALUES
('cfb6b648-f9cf-533b-983d-f0943c251d6a', 'wisata-alam', 'Wisata Alam', 'Wisata alam Desa Keseneng', 'Lanskap perbukitan, jalur jelajah, dan ruang alam desa menjadi daya tarik kunjungan yang dekat dengan kehidupan warga.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=85', 'bg-emerald-100 text-emerald-800', '3', 'titik kunjungan', 'Potensi Wisata Alam', 'Wisata alam Keseneng menonjolkan suasana perbukitan, titik pandang, dan pengalaman kunjungan yang tetap dekat dengan desa.', 'Data wisata alam disiapkan untuk memuat nama lokasi, akses, dokumentasi visual, narahubung, dan catatan singkat yang bisa dilengkapi admin desa.', 'Pengelola Wisata Desa Keseneng', 'Pengelola data wisata alam', 'wisata@keseneng.desa.id', 1, TRUE, 'published', 'Wisata alam Desa Keseneng', 'Lanskap perbukitan, jalur jelajah, dan ruang alam desa menjadi daya tarik kunjungan yang dekat dengan kehidupan warga.', CURRENT_TIMESTAMP),
('c5a2c199-c01a-5c24-855c-094f98e9d5e8', 'agro-tourism', 'Agro Tourism', 'Agro tourism dan kebun produktif', 'Sawah, kebun, dan aktivitas tani warga dapat dikemas sebagai pengalaman edukasi pertanian dan kunjungan berbasis desa.', 'https://images.unsplash.com/photo-1500382017468-9049fed747ef?auto=format&fit=crop&w=1200&q=85', 'bg-sage-100 text-sage-800', '312 ha', 'lahan produktif', 'Potensi Agro Tourism', 'Agro tourism menghubungkan aktivitas pertanian warga dengan pengalaman belajar, melihat proses tanam, dan mengenal komoditas desa.', 'Data agro tourism disiapkan untuk memuat lahan produktif, komoditas unggulan, kelompok tani, agenda panen, dan dokumentasi aktivitas yang bisa dilengkapi admin desa.', 'Kelompok Tani Desa Keseneng', 'Pengelola data agro tourism', 'agro@keseneng.desa.id', 2, TRUE, 'published', 'Agro tourism dan kebun produktif', 'Sawah, kebun, dan aktivitas tani warga dapat dikemas sebagai pengalaman edukasi pertanian dan kunjungan berbasis desa.', CURRENT_TIMESTAMP),
('850514ee-182d-5936-ac15-481bcb9e3463', 'umkm', 'UMKM', 'Produk lokal dan usaha warga', 'Olahan pangan, kerajinan, dan layanan warga disiapkan untuk memperluas pasar melalui publikasi digital desa.', 'https://images.unsplash.com/photo-1605522561233-768ad7a8fabf?auto=format&fit=crop&w=1200&q=85', 'bg-sky-100 text-sky-800', '48', 'usaha warga', 'Potensi UMKM', 'UMKM warga menjadi pintu penguatan ekonomi lokal melalui produk pangan, kerajinan, dan layanan desa.', 'Halaman detail UMKM disiapkan untuk menampung katalog produk, profil pelaku usaha, informasi kontak, dan cerita produksi agar produk lokal lebih mudah dipromosikan secara digital.', 'Forum UMKM Desa Keseneng', 'Pengelola data usaha warga', 'umkm@keseneng.desa.id', 3, TRUE, 'published', 'Produk lokal dan usaha warga', 'Olahan pangan, kerajinan, dan layanan warga disiapkan untuk memperluas pasar melalui publikasi digital desa.', CURRENT_TIMESTAMP),
('57d4e54e-ab88-56e0-8caf-f51a2c213699', 'seni-budaya', 'Seni & Budaya', 'Seni dan budaya Desa Keseneng', 'Jenis kesenian dan paguyuban aktif dikelola sebagai identitas budaya desa melalui dokumentasi yang mudah dibaca warga.', 'https://images.unsplash.com/photo-1508700115892-45ecd05ae2ad?auto=format&fit=crop&w=1200&q=85', 'bg-amber-100 text-amber-800', '4', 'jenis seni', 'Potensi Seni & Budaya', 'Seni dan budaya warga menjadi ruang ekspresi, regenerasi tradisi, dan penguatan identitas Desa Keseneng.', 'Data seni budaya disiapkan untuk memuat jenis kesenian, kelompok aktif, jadwal latihan, agenda pentas, dan dokumentasi cerita budaya yang bisa dilengkapi admin desa.', 'Komunitas Seni Keseneng', 'Pengelola kegiatan budaya', 'budaya@keseneng.desa.id', 4, TRUE, 'published', 'Seni dan budaya Desa Keseneng', 'Jenis kesenian dan paguyuban aktif dikelola sebagai identitas budaya desa melalui dokumentasi yang mudah dibaca warga.', CURRENT_TIMESTAMP)
