UPDATE potential_categories SET status = 'archived', is_active = FALSE WHERE slug NOT IN ('wisata-alam', 'agro-tourism', 'umkm', 'seni-budaya');

ON DUPLICATE KEY UPDATE label=VALUES(label), title=VALUES(title), summary=VALUES(summary), image_url=VALUES(image_url), accent_class_name=VALUES(accent_class_name), stat_value=VALUES(stat_value), stat_label=VALUES(stat_label), detail_eyebrow=VALUES(detail_eyebrow), detail_intro=VALUES(detail_intro), detail_description=VALUES(detail_description), contact_name=VALUES(contact_name), contact_role=VALUES(contact_role), contact_email=VALUES(contact_email), display_order=VALUES(display_order), is_active=VALUES(is_active), status=VALUES(status), seo_title=VALUES(seo_title), seo_description=VALUES(seo_description), published_at=VALUES(published_at);

DELETE FROM potential_highlights WHERE category_id IN ((SELECT id FROM potential_categories WHERE slug = 'wisata-alam'), (SELECT id FROM potential_categories WHERE slug = 'agro-tourism'), (SELECT id FROM potential_categories WHERE slug = 'umkm'), (SELECT id FROM potential_categories WHERE slug = 'seni-budaya'));

DELETE FROM potential_opportunities WHERE category_id IN ((SELECT id FROM potential_categories WHERE slug = 'wisata-alam'), (SELECT id FROM potential_categories WHERE slug = 'agro-tourism'), (SELECT id FROM potential_categories WHERE slug = 'umkm'), (SELECT id FROM potential_categories WHERE slug = 'seni-budaya'));

DELETE FROM potential_programs WHERE category_id IN ((SELECT id FROM potential_categories WHERE slug = 'wisata-alam'), (SELECT id FROM potential_categories WHERE slug = 'agro-tourism'), (SELECT id FROM potential_categories WHERE slug = 'umkm'), (SELECT id FROM potential_categories WHERE slug = 'seni-budaya'));

DELETE FROM potential_gallery_items WHERE category_id IN ((SELECT id FROM potential_categories WHERE slug = 'wisata-alam'), (SELECT id FROM potential_categories WHERE slug = 'agro-tourism'), (SELECT id FROM potential_categories WHERE slug = 'umkm'), (SELECT id FROM potential_categories WHERE slug = 'seni-budaya'));





ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), title=VALUES(title), summary=VALUES(summary), description=VALUES(description), image_url=VALUES(image_url), image_alt=VALUES(image_alt), status=VALUES(status), published_at=VALUES(published_at), display_order=VALUES(display_order), seo_title=VALUES(seo_title), seo_description=VALUES(seo_description);
